type IntelligencePanelProps = {
  selected: {
    type: "reason" | "competitor" | "deal";
    title: string;
    value?: number;
    secondary?: string;
    tertiary?: string;
    description?: string;
    action?: string;
  } | null;
  onClose: () => void;
};

export default function IntelligencePanel({
  selected,
  onClose,
}: IntelligencePanelProps) {
  if (!selected) return null;

  const formatValue = (
    value?: number,
    type?: "reason" | "competitor" | "deal"
