    if (value === undefined) return "—";

    if (type === "deal") {
      return new Intl.NumberFormat("en-IN", {
        maximumFractionDigits: 0,
      }).format(value);
    }

    if (type === "reason") {
      return `${value} lost deals`;
    }

    if (type === "competitor") {
      return `${value} deals`;
    }

    return String(value);
  };

  return (
    <>
