          <button
            type="button"
            onClick={onClose}
            className="flex h-8 w-8 items-center justify-center rounded-lg border border-[#1F2937] text-slate-400 transition hover:border-[#38BDF8]/40 hover:text-[#38BDF8]"
            aria-label="Close intelligence panel"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Content */}
