                <div className="mt-2 text-sm font-semibold uppercase text-[#38BDF8]">
                  {selected.type === "reason"
                    ? "LOSS REASON"
                    : selected.type === "competitor"
                      ? "COMPETITOR"
                      : "DEAL"}
