import DecisionPanel from "./components/DecisionPanel";

type Deal = {
  id: string;
  date: string;
  location: string;
  team: string;
  product: string;
  company: string;
  segment: string;
  reason: string;
  competitor: string;
  stage: string;
  value: number;
  priority: "HIGH" | "MEDIUM" | "LOW";
  action: string;
};

const reasonOrder = [
  "Price",
  "Competitor",
  "Product Fit",
  "Timing",
  "Budget",
];

const segmentOrder = ["Enterprise", "Mid-Market", "SMB"];

const competitorOrder = [
  "Salesforce",
  "Microsoft",
  "Zoho",
  "HubSpot",
  "AWS",
  "Power BI",
  "Tableau",
  "Azure",
];

function formatCurrency(value: number) {
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits: 0,
  }).format(value);
}

export default function Home() {
  const [showInfo, setShowInfo] = useState(false);
  const [deals, setDeals] = useState<Deal[]>([]);
  const [loading, setLoading] = useState(true);
  const [apiError, setApiError] = useState("");

  const [locationFilter, setLocationFilter] = useState("ALL");
  const [teamFilter, setTeamFilter] = useState("ALL");
  const [productFilter, setProductFilter] = useState("ALL");
  const [segmentFilter, setSegmentFilter] = useState("ALL");
  const [reasonFilter, setReasonFilter] = useState("ALL");
  const [priorityFilter, setPriorityFilter] = useState("ALL");

  useEffect(() => {
    const apiBaseUrl = process.env.NEXT_PUBLIC_API_URL || "";

    fetch(`${apiBaseUrl}/api/deals`)
      .then((response) => {
        if (!response.ok) {
          throw new Error(`API request failed: ${response.status}`);
        }

        return response.json();
      })
      .then((data: Deal[]) => {
        setDeals(data);
        setApiError("");
      })
      .catch((error) => {
        console.error("Failed to load deals:", error);
        setApiError(
          "Unable to load CRM data from the FastAPI backend.",
        );
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  const filteredDeals = useMemo(() => {
    return deals.filter((deal) => {
      return (
        (locationFilter === "ALL" ||
          deal.location === locationFilter) &&
        (teamFilter === "ALL" || deal.team === teamFilter) &&
        (productFilter === "ALL" ||
          deal.product === productFilter) &&
        (segmentFilter === "ALL" ||
          deal.segment === segmentFilter) &&
        (reasonFilter === "ALL" || deal.reason === reasonFilter) &&
        (priorityFilter === "ALL" ||
          deal.priority === priorityFilter)
      );
    });
  }, [
    deals,
    locationFilter,
    teamFilter,
    productFilter,
    segmentFilter,
    reasonFilter,
    priorityFilter,
  ]);

  const totalLost = filteredDeals.length;

  const totalValue = filteredDeals.reduce(
    (sum, deal) => sum + deal.value,
    0,
  );

  const highPriority = filteredDeals.filter(
    (deal) => deal.priority === "HIGH",
  ).length;

  const averageDealValue = totalLost > 0 ? totalValue / totalLost : 0;

  const lossReasons = reasonOrder
    .map((reason) => ({
      reason,
      count: filteredDeals.filter((deal) => deal.reason === reason)
        .length,
    }))
    .filter((item) => item.count > 0)
    .sort((a, b) => b.count - a.count);

  const topReason = lossReasons[0]?.reason ?? "No data";

  const competitorCounts = competitorOrder
    .map((competitor) => {
      const losses = filteredDeals.filter(
        (deal) => deal.competitor === competitor,
      ).length;

      return {
        competitor,
        wins: 0,
        losses,
      };
    })
    .filter((item) => item.losses > 0);

  const topCompetitor =
    competitorCounts.length > 0
      ? [...competitorCounts].sort(
          (a, b) => b.losses - a.losses,
        )[0].competitor
      : "No data";

  const segments = segmentOrder.flatMap((segment) =>
    reasonOrder.map((reason) => ({
      segment,
      reason,
      value: filteredDeals.filter(
        (deal) => deal.segment === segment && deal.reason === reason,
      ).length,
    })),
  );

  const recoveryItems = [...filteredDeals]
    .sort((a, b) => {
      const priorityRank = {
        HIGH: 3,
        MEDIUM: 2,
        LOW: 1,
      };

      return (
        priorityRank[b.priority] - priorityRank[a.priority] ||
        b.value - a.value
      );
    })
    .map((deal) => ({
      id: deal.id,
      company: deal.company,
      reason: deal.reason,
      competitor: deal.competitor,
      stage: deal.stage,
      value: deal.value,
      priority: deal.priority,
      action: deal.action,
    }));

  const downloadJSON = () => {
    const blob = new Blob([JSON.stringify(filteredDeals, null, 2)], {
      type: "application/json",
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = "lost-deal-recovery-data.json";
    link.click();

    URL.revokeObjectURL(url);
  };

  const downloadCSV = () => {
    const headers = [
      "ID",
      "Date",
      "Location",
      "Team",
      "Product",
      "Company",
      "Segment",
      "Loss Reason",
      "Competitor",
      "Stage",
      "Value",
      "Priority",
      "Recommended Action",
    ];

    const rows = filteredDeals.map((deal) => [
      deal.id,
      deal.date,
      deal.location,
      deal.team,
      deal.product,
      deal.company,
      deal.segment,
      deal.reason,
      deal.competitor,
      deal.stage,
      deal.value,
      deal.priority,
      deal.action,
    ]);

    const csv = [headers, ...rows]
      .map((row) =>
        row
          .map((value) => `"${String(value).replaceAll('"', '""')}"`)
          .join(","),
      )
      .join("\n");

    const blob = new Blob([csv], {
      type: "text/csv;charset=utf-8;",
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = "lost-deal-recovery-data.csv";
    link.click();

    URL.revokeObjectURL(url);
  };

  return (
    <main className="min-h-screen bg-[#030712] text-slate-100">
